      if (!client) throw new Error("无飞书 client 在线");
      if (!String(peerId).startsWith("p2p:")) throw new Error("飞书群聊推送暂不支持（仅 p2p 私聊）");
      await sendFeishuText(client, String(peerId).slice(4), text);
