    releaseTarget: (channel, peerId) => bridge.releaseTarget(channel, peerId),
    release: (keepCount) => bridge.release(keepCount),
    getCfg: () => getChannelsCfg(),
    setCfg: (patch) => setChannelsCfg(patch),
