  /** 处理 /sessions /bind /status 命令；命中返回 true（不再转发给 agent）。 */
  async function handleCommand(channel, peerId, text, sessionsSvc) {
    const t = String(text || "").trim();
    const reply = (msg) => deps.push(channel, peerId, msg);
