          first.resolve(outcome);
          await reply(outcome === "allowed-once" ? "✅ 已批准" : "🚫 已拒绝");
          return true;
        }
      }
    }
    return false;
  }

  return {
    bindings,
    handleCommand,
    notifySession,
    stop: () => { try { stopApproval(); } catch {} try { stopStatus(); } catch {} },
  };
